            {"ref": "POK:1170", "status": "partial", "note": "Pokorny supports 'npers. barra (*varnak) lamb' but says nothing of kalâğ or varğeneh."},
            {"ref": "SOD:398", "status": "partial", "note": "Entry 9855 (p. 399) supports the falcon word only, through the Sogdian cognate."},
            {"ref": "BQT", "status": "not_found", "note": "No page given. Grepping BQT_v3_pages.txt for 'کلاغ' found only gloss uses (l.12691 'از جنس کلاغ', l.13845 'زاغ، کلاغ'). 'ورغنه' was not found in BQT_v4_pages.txt or BQT_v5_pages.txt."}
          ],
          "consulted": [
            {"src": "HUB", "where": "HUB.txt l.9287", "stance": "supports", "note": "'barra, bara Lamm aus *varnak, idg. vr̥ren-, skr. urana-, arm. garn' (barreh only)"},
            {"src": "PHD", "where": "PHD.txt l.607", "stance": "partial", "note": "'warrag … N barra' supports barreh. 'warāɣ [wl'g | J bry] crow' gives no NP kalāγ, only a Judeo-Persian cognate."},
            {"src": "ARY", "where": "ARY_latin_index_pages.txt [pdf page 125-126] s.v. بره", "stance": "supports", "note": "Cognates 'URANA (SANSKRIT)', 'ARĒN (GREEK)', 'GARN (ARMENIAN)', 'VARAK, WARRAG (PAHLAVI)'; refs 'POKORNY', 'MACKENZIE (LAMB) 121', 'BUCK 156-160' (barreh only)."},
            {"src": "BQT", "where": "BQT_v1_pages.txt leaf 488", "stance": "silent", "note": "The بره headwords are present, but the OCR is too poor to read Mo'in's footnote."}
          ]
        }
